'use strict';

const crypto = require('node:crypto');
const { promisify } = require('node:util');
const path = require('node:path');
const express = require('express');
const helmet = require('helmet');
const { rateLimit } = require('express-rate-limit');
const db = require('./db');

const scrypt = promisify(crypto.scrypt);
const app = express();
const PORT = Number.parseInt(process.env.PORT || '3000', 10);
const SESSION_COOKIE = 'minimalist_blog_session';
const SESSION_TTL_MS = 30 * 60 * 1000;
const COOKIE_SECURE = process.env.NODE_ENV === 'production';
const APP_ORIGIN = process.env.APP_ORIGIN ? new URL(process.env.APP_ORIGIN).origin : null;

if (process.env.TRUST_PROXY === '1') app.set('trust proxy', 1);
app.disable('x-powered-by');
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:'],
      connectSrc: ["'self'"],
      objectSrc: ["'none'"],
      baseUri: ["'self'"],
      frameAncestors: ["'none'"],
      formAction: ["'self'"]
    }
  },
  crossOriginEmbedderPolicy: false,
  referrerPolicy: { policy: 'same-origin' }
}));
app.use(express.json({ limit: '128kb', type: 'application/json' }));

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 20,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: { error: 'Too many attempts. Please try again later.' }
});

const statements = {
  userByIdentity: db.prepare(`
    SELECT id, username, email, password_hash AS passwordHash
    FROM users WHERE username_normalized = ? OR email_normalized = ? LIMIT 1
  `),
  insertUser: db.prepare(`
    INSERT INTO users (id, username, username_normalized, email, email_normalized, password_hash, created_at)
    VALUES (@id, @username, @usernameNormalized, @email, @emailNormalized, @passwordHash, @createdAt)
  `),
  insertSession: db.prepare(`
    INSERT INTO sessions (id_hash, user_id, created_at, last_activity_at) VALUES (?, ?, ?, ?)
  `),
  sessionUser: db.prepare(`
    SELECT s.id_hash AS idHash, s.last_activity_at AS lastActivityAt,
           u.id, u.username, u.email
    FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.id_hash = ?
  `),
  touchSession: db.prepare('UPDATE sessions SET last_activity_at = ? WHERE id_hash = ?'),
  deleteSession: db.prepare('DELETE FROM sessions WHERE id_hash = ?'),
  deleteExpiredSessions: db.prepare('DELETE FROM sessions WHERE last_activity_at <= ?'),
  postById: db.prepare(`
    SELECT p.id, p.author_id AS authorId, p.title, p.content,
           p.created_at AS createdAt, p.modified_at AS modifiedAt,
           u.username AS author
    FROM posts p JOIN users u ON u.id = p.author_id WHERE p.id = ?
  `),
  insertPost: db.prepare(`
    INSERT INTO posts (id, author_id, title, content, created_at, modified_at)
    VALUES (@id, @authorId, @title, @content, @createdAt, @modifiedAt)
  `),
  updatePost: db.prepare(`
    UPDATE posts SET title = @title, content = @content, modified_at = @modifiedAt
    WHERE id = @id AND author_id = @authorId
  `),
  deletePost: db.prepare('DELETE FROM posts WHERE id = ? AND author_id = ?')
};

function jsonError(res, status, message, fields) {
  const payload = { error: message };
  if (fields) payload.fields = fields;
  return res.status(status).json(payload);
}

function normalizeText(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function codePointLength(value) {
  return Array.from(value).length;
}

function validateRegistration(input) {
  const username = normalizeText(input.username);
  const email = normalizeText(input.email);
  const password = typeof input.password === 'string' ? input.password : '';
  const errors = {};

  if (!/^[A-Za-z0-9_]{3,30}$/.test(username)) {
    errors.username = 'Use 3–30 letters, numbers, or underscores.';
  }
  if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.email = 'Enter a valid email address (up to 254 characters).';
  }
  const passwordLength = codePointLength(password);
  if (passwordLength < 12 || passwordLength > 128) {
    errors.password = 'Use a password between 12 and 128 characters.';
  }
  return { errors, username, email, password };
}

function validatePost(input) {
  const title = normalizeText(input.title);
  const content = normalizeText(input.content);
  const errors = {};
  if (!title || codePointLength(title) > 120) {
    errors.title = 'Title is required and must be no more than 120 characters.';
  }
  if (!content || codePointLength(content) > 10000) {
    errors.content = 'Content is required and must be no more than 10,000 characters.';
  }
  return { errors, title, content };
}

function sessionToken(req) {
  const value = req.get('cookie') || '';
  const item = value.split(';').map(part => part.trim())
    .find(part => part.startsWith(`${SESSION_COOKIE}=`));
  // Session tokens are base64url-safe and never require URL decoding.
  return item ? item.slice(SESSION_COOKIE.length + 1) : '';
}

function hashToken(token) {
  return crypto.createHash('sha256').update(token).digest('hex');
}

function setSessionCookie(res, token) {
  res.cookie(SESSION_COOKIE, token, {
    httpOnly: true,
    secure: COOKIE_SECURE,
    sameSite: 'strict',
    path: '/',
    maxAge: SESSION_TTL_MS
  });
}

function clearSessionCookie(res) {
  res.clearCookie(SESSION_COOKIE, {
    httpOnly: true,
    secure: COOKIE_SECURE,
    sameSite: 'strict',
    path: '/'
  });
}

function requireSameOrigin(req, res, next) {
  if (!req.get('x-requested-with') || req.get('x-requested-with') !== 'XMLHttpRequest') {
    return jsonError(res, 403, 'Request could not be verified.');
  }
  const originHeader = req.get('origin');
  const refererHeader = req.get('referer');
  let sourceOrigin;
  try {
    sourceOrigin = originHeader ? new URL(originHeader).origin :
      (refererHeader ? new URL(refererHeader).origin : '');
  } catch {
    return jsonError(res, 403, 'Request could not be verified.');
  }
  const expectedOrigin = APP_ORIGIN || `${req.protocol}://${req.get('host')}`;
  if (!sourceOrigin || sourceOrigin !== expectedOrigin) {
    return jsonError(res, 403, 'Request could not be verified.');
  }
  next();
}

function requireAuth(req, res, next) {
  const token = sessionToken(req);
  if (!token) return jsonError(res, 401, 'Please log in to continue.');
  const idHash = hashToken(token);
  const session = statements.sessionUser.get(idHash);
  const now = Date.now();
  if (!session || now - Date.parse(session.lastActivityAt) >= SESSION_TTL_MS) {
    if (session) statements.deleteSession.run(idHash);
    clearSessionCookie(res);
    return jsonError(res, 401, 'Your session expired. Please log in again.');
  }
  const nowIso = new Date(now).toISOString();
  statements.touchSession.run(nowIso, idHash);
  req.user = { id: session.id, username: session.username, email: session.email };
  req.sessionIdHash = idHash;
  next();
}

function publicUser(user) {
  return { id: user.id, username: user.username, email: user.email };
}

function getFeed(req, res) {
  const q = typeof req.query.q === 'string' ? req.query.q.trim() : '';
  const sort = req.query.sort;
  if (q.length > 100) return jsonError(res, 400, 'Search must be no more than 100 characters.');
  const allowedSorts = ['title-asc', 'title-desc', 'modified-desc', 'modified-asc'];
  if (sort !== undefined && !allowedSorts.includes(sort)) {
    return jsonError(res, 400, 'Unsupported sort option.');
  }
  const orders = {
    'title-asc': 'p.title COLLATE NOCASE ASC, p.created_at DESC, p.id ASC',
    'title-desc': 'p.title COLLATE NOCASE DESC, p.created_at DESC, p.id ASC',
    'modified-desc': 'p.modified_at DESC, p.created_at DESC, p.id ASC',
    'modified-asc': 'p.modified_at ASC, p.created_at DESC, p.id ASC'
  };
  const orderBy = orders[sort] || 'p.created_at DESC, p.id ASC';
  const pattern = `%${q.replace(/[\\%_]/g, '\\$&')}%`;
  const posts = db.prepare(`
    SELECT p.id, p.title, p.content, p.created_at AS createdAt,
           p.modified_at AS modifiedAt, u.username AS author
    FROM posts p JOIN users u ON u.id = p.author_id
    WHERE (? = '' OR p.title LIKE ? ESCAPE '\\' COLLATE NOCASE
                    OR p.content LIKE ? ESCAPE '\\' COLLATE NOCASE)
    ORDER BY ${orderBy}
  `).all(q, pattern, pattern);
  res.json({ posts });
}

app.get('/api/auth/session', (req, res) => {
  const token = sessionToken(req);
  if (!token) return jsonError(res, 401, 'Not signed in.');
  const idHash = hashToken(token);
  const session = statements.sessionUser.get(idHash);
  if (!session || Date.now() - Date.parse(session.lastActivityAt) >= SESSION_TTL_MS) {
    if (session) statements.deleteSession.run(idHash);
    clearSessionCookie(res);
    return jsonError(res, 401, 'Your session expired. Please log in again.');
  }
  statements.touchSession.run(new Date().toISOString(), idHash);
  return res.json({ user: publicUser(session) });
});

app.post('/api/auth/register', authLimiter, requireSameOrigin, async (req, res, next) => {
  try {
    const { errors, username, email, password } = validateRegistration(req.body || {});
    if (Object.keys(errors).length) return jsonError(res, 400, 'Please correct the highlighted fields.', errors);
    const usernameNormalized = username.toLowerCase();
    const emailNormalized = email.toLowerCase();
    if (statements.userByIdentity.get(usernameNormalized, usernameNormalized) ||
        statements.userByIdentity.get(emailNormalized, emailNormalized)) {
      return jsonError(res, 409, 'That username or email is already registered.');
    }
    const salt = crypto.randomBytes(16);
    const derivedKey = await scrypt(password, salt, 64, { N: 16384, r: 8, p: 1, maxmem: 64 * 1024 * 1024 });
    const passwordHash = `scrypt$${salt.toString('hex')}$${Buffer.from(derivedKey).toString('hex')}`;
    try {
      statements.insertUser.run({
        id: crypto.randomUUID(), username, usernameNormalized, email,
        emailNormalized, passwordHash, createdAt: new Date().toISOString()
      });
    } catch (error) {
      if (error.code === 'SQLITE_CONSTRAINT_UNIQUE') {
        return jsonError(res, 409, 'That username or email is already registered.');
      }
      throw error;
    }
    return res.status(201).json({ message: 'Account created. Please log in.' });
  } catch (error) {
    next(error);
  }
});

app.post('/api/auth/login', authLimiter, requireSameOrigin, async (req, res, next) => {
  try {
    const identity = normalizeText(req.body && req.body.identity);
    const password = req.body && typeof req.body.password === 'string' ? req.body.password : '';
    if (!identity || !password || identity.length > 254 || codePointLength(password) > 128) {
      return jsonError(res, 400, 'Enter your username or email and password.');
    }
    const normalized = identity.toLowerCase();
    const user = statements.userByIdentity.get(normalized, normalized);
    let verified = false;
    if (user && user.passwordHash.startsWith('scrypt$')) {
      const [, saltHex, hashHex] = user.passwordHash.split('$');
      const expected = Buffer.from(hashHex, 'hex');
      const actual = Buffer.from(await scrypt(password, Buffer.from(saltHex, 'hex'), expected.length, {
        N: 16384, r: 8, p: 1, maxmem: 64 * 1024 * 1024
      }));
      verified = expected.length === actual.length && crypto.timingSafeEqual(expected, actual);
    } else {
      // Equalize the work for unknown identities to reduce account enumeration timing.
      await scrypt(password || 'invalid', Buffer.alloc(16), 64, { N: 16384, r: 8, p: 1, maxmem: 64 * 1024 * 1024 });
    }
    if (!verified) return jsonError(res, 401, 'Invalid username/email or password.');

    const previousToken = sessionToken(req);
    if (previousToken) statements.deleteSession.run(hashToken(previousToken));
    const token = crypto.randomBytes(32).toString('base64url');
    const now = new Date().toISOString();
    statements.insertSession.run(hashToken(token), user.id, now, now);
    setSessionCookie(res, token);
    return res.json({ user: publicUser(user) });
  } catch (error) {
    next(error);
  }
});

app.post('/api/auth/logout', requireSameOrigin, requireAuth, (req, res) => {
  statements.deleteSession.run(req.sessionIdHash);
  clearSessionCookie(res);
  res.status(204).end();
});

app.get('/api/posts', getFeed);

app.get('/api/posts/:id', (req, res) => {
  const post = statements.postById.get(req.params.id);
  if (!post) return jsonError(res, 404, 'Post not found.');
  res.json({ post });
});

app.post('/api/posts', requireSameOrigin, requireAuth, (req, res) => {
  const { errors, title, content } = validatePost(req.body || {});
  if (Object.keys(errors).length) return jsonError(res, 400, 'Please correct the highlighted fields.', errors);
  const now = new Date().toISOString();
  const post = {
    id: crypto.randomUUID(), authorId: req.user.id, title, content,
    createdAt: now, modifiedAt: now
  };
  statements.insertPost.run(post);
  res.status(201).json({ post: statements.postById.get(post.id) });
});

app.patch('/api/posts/:id', requireSameOrigin, requireAuth, (req, res) => {
  const post = statements.postById.get(req.params.id);
  if (!post) return jsonError(res, 404, 'Post not found.');
  if (post.authorId !== req.user.id) return jsonError(res, 403, 'Only the author can edit this post.');
  const { errors, title, content } = validatePost(req.body || {});
  if (Object.keys(errors).length) return jsonError(res, 400, 'Please correct the highlighted fields.', errors);
  statements.updatePost.run({
    id: post.id, authorId: req.user.id, title, content, modifiedAt: new Date().toISOString()
  });
  res.json({ post: statements.postById.get(post.id) });
});

app.delete('/api/posts/:id', requireSameOrigin, requireAuth, (req, res) => {
  const post = statements.postById.get(req.params.id);
  if (!post) return jsonError(res, 404, 'Post not found.');
  if (post.authorId !== req.user.id) return jsonError(res, 403, 'Only the author can delete this post.');
  statements.deletePost.run(post.id, req.user.id);
  res.status(204).end();
});

app.use('/api', (req, res) => jsonError(res, 404, 'API route not found.'));
app.use(express.static(path.join(__dirname, 'public'), { index: 'index.html', maxAge: COOKIE_SECURE ? '1h' : 0 }));
app.get('*', (req, res, next) => {
  if (req.method !== 'GET') return next();
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.use((error, req, res, next) => {
  if (res.headersSent) return next(error);
  if (error.type === 'entity.too.large') {
    return jsonError(res, 413, 'Request body is too large.');
  }
  if (error instanceof SyntaxError && error.status === 400 && 'body' in error) {
    return jsonError(res, 400, 'Request body must be valid JSON.');
  }
  console.error('Request failed:', error.message);
  return jsonError(res, 500, 'Something went wrong. Please try again.');
});

const cleanupTimer = setInterval(() => {
  const cutoff = new Date(Date.now() - SESSION_TTL_MS).toISOString();
  statements.deleteExpiredSessions.run(cutoff);
}, 60 * 60 * 1000);
cleanupTimer.unref();

const server = app.listen(PORT, () => {
  console.log(`Minimalist Blog listening on port ${PORT}`);
});

function shutdown() {
  server.close(() => {
    clearInterval(cleanupTimer);
    db.close();
    process.exit(0);
  });
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
